import { useEffect, useReducer, useState } from "react";
import axios from "../app/api/axios";
import initialState from "../store";
import reducer from "../reducer";
import { Link } from "react-router-dom";

const Register = () => {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [confirmPwd, setConfirmPwd] = useState("");
  const userRef = useRef();
  const errRef = useRef();
  const [isPassword, setisPassword] = useState("password");
  const [isPassword2, setisPassword2] = useState("password");
  const [passwordCheck, setPasswordCheck] = useState(faEyeSlash);
  const [verified, setVerified] = useState(false);
  const now = new Date();

  const USER_REGEX = /^[A-z][A-z0-9-_]{2,23}$/;
  // const EMAIL_REGEX = /^(?=.*[a-z])(?=.*[!@#$%]).{3,50}$/;
  const PWD_REGEX = /^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#$%]).{8,24}$/;

  const getUsers = async () => {
    const response = await axios.get("/register");
    console.log(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newUser = {
      username: username,
      email: email,
      password: pwd,
      date: now,
    };
    console.log(newUser);
    const response = await axios.post("/register", newUser);
  };

  // useEffect(() => {
  //   getUsers();
  // }, []);

  return (
    <div className="register">
      <h3>Register</h3>
      <form className="register-form" onSubmit={handleSubmit}>
        <label>name</label>
        <input
          value={username}
          type="text"
          onChange={(e) => setUsername(e.target.value)}
        />
        <label>email</label>
        <input
          value={email}
          type="text"
          onChange={(e) => setEmail(e.target.value)}
        />
        <label>password</label>
        <input
          value={pwd}
          type="text"
          onChange={(e) => setPwd(e.target.value)}
        />
        <label>confrirm password</label>
        <input
          value={confirmPwd}
          type="text"
          onChange={(e) => setConfirmPwd(e.target.value)}
        />
        <br />
        <button type="submit">sign up</button>
      </form>
      <article className="sign-up-cont">
        <p>Already registered? </p>

        {/*put router link here*/}
        <Link
          style={{
            color: "blue",
          }}
          to={"/login"}
        >
          Sign In
        </Link>
      </article>
    </div>
  );
};

export default Register;
